// RemoveConsumer removes a consumer from the queue.
// Ordering key assignments for this consumer are cleared so they
// get reassigned to remaining consumers on next delivery.
func (q *Queue) RemoveConsumer(ch <-chan *Message) {
	q.mu.Lock()
	defer q.mu.Unlock()
	for i, c := range q.consumers {
		if c.Ch == ch {
			// Clear ordering key assignments for this consumer
			for key, assigned := range q.keyAssignments {
				if assigned == c {
					delete(q.keyAssignments, key)
				}
			}
			q.consumers = append(q.consumers[:i], q.consumers[i+1:]...)
			close(c.Ch)
			return
		}
	}
}

// Ack acknowledges a message, removing it from in-flight.
func (q *Queue) Ack(messageID string) bool {
	q.mu.Lock()
	defer q.mu.Unlock()
	if _, ok := q.inFlight[messageID]; ok {
		delete(q.inFlight, messageID)
		q.tryDeliver() // Deliver next message now that channel has space
		return true
	}
	return false
}

// NackResult indicates what happened to a nacked message.
type NackResult struct {
	Found   bool     // Was the message found?
	Message *Message // The message (for DLQ handling)
	ToDLQ   bool     // Should message go to DLQ?
}

// Nack negatively acknowledges a message.
// If requeue is true, the message is put back in the queue (subject to retry limits).
// Returns NackResult indicating what to do with the message.
func (q *Queue) Nack(messageID string, requeue bool) NackResult {
	q.mu.Lock()
	defer q.mu.Unlock()

	msg, ok := q.inFlight[messageID]
	if !ok {
		return NackResult{Found: false}
	}
	delete(q.inFlight, messageID)

	if !requeue {
		// Explicit reject without requeue - send to DLQ if policy allows
		if q.failurePolicy == FailurePolicyDLQ {
			return NackResult{Found: true, Message: msg, ToDLQ: true}
		}
		return NackResult{Found: true, Message: msg, ToDLQ: false}
	}

	// Check if we've exceeded max retries
	if q.failurePolicy != FailurePolicyInfinite && msg.Attempt >= q.maxRetries {
		switch q.failurePolicy {
		case FailurePolicyDLQ:
			return NackResult{Found: true, Message: msg, ToDLQ: true}
		case FailurePolicyDrop:
			return NackResult{Found: true, Message: msg, ToDLQ: false}
		}
	}

	// Requeue the message
	msg.VisibleAt = time.Now()
	q.messages = append(q.messages, msg)
	q.tryDeliver()
	return NackResult{Found: true, Message: msg, ToDLQ: false}
}

// Len returns the number of messages in the queue (not in-flight).
func (q *Queue) Len() int {
	q.mu.Lock()
	defer q.mu.Unlock()
	return len(q.messages)
}

// InFlightLen returns the number of in-flight messages.
func (q *Queue) InFlightLen() int {
	q.mu.Lock()
	defer q.mu.Unlock()
	return len(q.inFlight)
}

// RequeueExpired moves expired in-flight messages back to the queue.
func (q *Queue) RequeueExpired() {
	q.mu.Lock()
	now := time.Now()
	for id, msg := range q.inFlight {
		if msg.VisibleAt.Before(now) {
			delete(q.inFlight, id)
			msg.VisibleAt = now
			q.messages = append(q.messages, msg)
		}
	}
	q.tryDeliver()
	groups := make([]*ConsumerGroup, 0, len(q.groups))
	for _, g := range q.groups {
		groups = append(groups, g)
	}
	q.mu.Unlock()
	for _, g := range groups {
		g.RequeueExpired()
	}
}

// GetOrCreateGroup returns the consumer group with the given name, creating it if needed.
func (q *Queue) GetOrCreateGroup(groupName string) *ConsumerGroup {
	q.mu.Lock()
	defer q.mu.Unlock()
	if q.groups == nil {
		q.groups = make(map[string]*ConsumerGroup)
	}
	g, ok := q.groups[groupName]
	if !ok {
		g = NewConsumerGroup(groupName, q.name)
		q.groups[groupName] = g
	}
	return g
}

// GetGroup returns the consumer group with the given name, or nil.
func (q *Queue) GetGroup(groupName string) *ConsumerGroup {
	q.mu.Lock()
	defer q.mu.Unlock()
	if q.groups == nil {
		return nil
	}
	return q.groups[groupName]
}

// RemoveGroup removes a consumer group from the queue.
func (q *Queue) RemoveGroup(groupName string) {
	q.mu.Lock()
	defer q.mu.Unlock()
	delete(q.groups, groupName)
}

// RequeueExpiredGroups requeues expired in-flight messages in all groups.
func (q *Queue) RequeueExpiredGroups() {
	q.mu.Lock()
	groups := make([]*ConsumerGroup, 0, len(q.groups))
	for _, g := range q.groups {
		groups = append(groups, g)
	}
	q.mu.Unlock()
	for _, g := range groups {
		g.RequeueExpired()
	}
}

// ReapDeadGroupMembers checks all groups for dead members. Returns removed member IDs.
func (q *Queue) ReapDeadGroupMembers() []string {
	q.mu.Lock()
	groups := make([]*ConsumerGroup, 0, len(q.groups))
	for _, g := range q.groups {
		groups = append(groups, g)
	}
	q.mu.Unlock()

	var dead []string
	for _, g := range groups {
		dead = append(dead, g.ReapDeadMembers()...)
	}
	return dead
}

// ExtendVisibility extends the visibility timeout for an in-flight message.
// Returns the new visibility timestamp, or zero time if message not found.
func (q *Queue) ExtendVisibility(messageID string, extension time.Duration) time.Time {
	q.mu.Lock()
	defer q.mu.Unlock()
	msg, ok := q.inFlight[messageID]
	if !ok {
		return time.Time{}
	}
	msg.VisibleAt = time.Now().Add(extension)
	return msg.VisibleAt
}

// ConsumerCount returns the number of active consumers.
func (q *Queue) ConsumerCount() int {
	q.mu.Lock()
	defer q.mu.Unlock()
	return len(q.consumers)
}

// Peek returns up to n messages from the head of the queue without removing them.
func (q *Queue) Peek(n int) []*Message {
	q.mu.Lock()
	defer q.mu.Unlock()
	if n > len(q.messages) {
		n = len(q.messages)
	}
	result := make([]*Message, n)
	copy(result, q.messages[:n])
	return result
}

// Purge removes all messages from the queue and returns the count removed.
func (q *Queue) Purge() int {
	q.mu.Lock()
	defer q.mu.Unlock()
	count := len(q.messages) + len(q.inFlight)
	q.messages = nil
	q.inFlight = make(map[string]*Message)
	return count
}

