		if err != nil {
			continue
		}
		schemas = append(schemas, schemaSummary{
			Queue:       s.Queue,
			MessageType: s.MessageType,
			Version:     s.Version,
		})
	}
	writeJSON(w, http.StatusOK, schemas)
}

