	conn.Write(protocol.EncodeFrame(protocol.OpConsume, consumeData))

	time.Sleep(50 * time.Millisecond)

	// Send heartbeat
	hbReq := &protocol.HeartbeatRequest{Group: "hb-group", Queue: "hb-queue"}
