// retentionLoop periodically runs retention cleanup on stream queues.
func (b *Broker) retentionLoop() {
	ticker := time.NewTicker(60 * time.Second)
	defer ticker.Stop()
	for {
		select {
		case <-ticker.C:
			b.mu.RLock()
			for _, sq := range b.streamQueues {
				sq.RunRetention()
			}
			b.mu.RUnlock()
		case <-b.done:
