// RetryDLQ moves all pending DLQ messages back to their original queue.
func (b *Broker) RetryDLQ(name string) (int, error) {
	dlqName := DLQName(name)
	dlq := b.GetQueue(dlqName)
	if dlq == nil || dlq.Len() == 0 {
		return 0, nil
	}

	msgs := dlq.Peek(dlq.Len())
	q := b.GetOrCreateQueue(name)
	retried := 0
	for _, msg := range msgs {
		copy := *msg
		copy.Queue = name
		copy.Attempt = 0
		copy.VisibleAt = time.Now()
		if b.storage != nil {
			if err := b.storage.SaveMessage(&copy); err != nil {
				return retried, err
			}
			if err := b.storage.DeleteMessage(dlqName, msg.ID); err != nil {
				if rbErr := b.storage.DeleteMessage(name, copy.ID); rbErr != nil {
					return retried, fmt.Errorf("delete DLQ message %s from %s failed: %w; rollback from %s also failed: %w", msg.ID, dlqName, err, name, rbErr)
				}
				return retried, err
			}
		}
		if err := q.Enqueue(&copy); err != nil {
			if b.storage != nil {
				if rbErr := b.storage.SaveMessage(msg); rbErr != nil {
					return retried, fmt.Errorf("enqueue retry message %s to %s failed: %w; DLQ restore to %s also failed: %w", copy.ID, name, err, dlqName, rbErr)
				}
				if rbErr := b.storage.DeleteMessage(name, copy.ID); rbErr != nil {
					return retried, fmt.Errorf("enqueue retry message %s to %s failed: %w; original queue rollback also failed: %w", copy.ID, name, err, rbErr)
				}
			}
			return retried, err
		}
		dlq.Remove(msg.ID)
		retried++
	}
	return retried, nil
}

