			msg.VisibleAt = now.Add(c.VisibilityTimeout)
			q.nextIdx = (idx + 1) % len(q.consumers)
			return true
		default:
			// Channel full, try next consumer
		}
	}
	return false
}

func cloneMessage(msg *Message) *Message {
	cloned := *msg
	cloned.Attempt = msg.Attempt + 1
	if msg.Headers != nil {
		cloned.Headers = make(map[string]string, len(msg.Headers))
		for k, v := range msg.Headers {
			cloned.Headers[k] = v
		}
	}
	return &cloned
}

// Dequeue returns a consumer channel for receiving messages.
func (q *Queue) Dequeue(visibilityTimeout time.Duration) <-chan *Message {
	ch := make(chan *Message, 1)
	c := &Consumer{
		Ch:                ch,
		VisibilityTimeout: visibilityTimeout,
	}

	q.mu.Lock()
	q.consumers = append(q.consumers, c)
	q.tryDeliver()
	q.mu.Unlock()

	return ch

