	}

	recovered := b2.GetQueue("retry-attempt")
	if recovered == nil {
		t.Fatal("queue not recovered")
	}
	next := <-recovered.Dequeue(30 * time.Second)
	if next.Attempt != 2 {
		t.Fatalf("expected retry attempt to survive restart and deliver attempt 2, got %d", next.Attempt)
	}
}

